// Small questions to the network: does an address answer, is a port taken.
import { connect } from "node:net";
export async function answers(url, timeoutMs = 1500) {
    try {
        const response = await fetch(url, {
            signal: AbortSignal.timeout(timeoutMs),
            redirect: "manual",
        });
        await response.body?.cancel();
        return response.status < 400;
    }
    catch {
        return false;
    }
}
// True when something accepts connections on the port, whatever it is, on
// IPv4 or IPv6 (a development server may listen on only one of them, and
// "localhost" in a browser reaches either).
export async function portTaken(port, timeoutMs = 1000) {
    const taken = await Promise.all(["127.0.0.1", "::1"].map((host) => takenOn(port, host, timeoutMs)));
    return taken.some(Boolean);
}
async function takenOn(port, host, timeoutMs) {
    return await new Promise((resolve) => {
        const socket = connect({ port, host });
        const done = (taken) => {
            socket.destroy();
            resolve(taken);
        };
        socket.setTimeout(timeoutMs, () => {
            done(false);
        });
        socket.once("connect", () => {
            done(true);
        });
        socket.once("error", () => {
            done(false);
        });
    });
}
